head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[checkcombobox > M > setItemDisabled]<br/>컴포넌트에서 특정 아이템을 비활성화 상태를 설정합니다.",
    "validation" : [        
        "아이템이 BindItemSet 으로 정의된 경우에 동작합니다. ",
        "index(필수) 파라미터로 비활성화 상태를 설정하려는 아이템의 인덱스를 문자열로 설정합니다.",
        "아이템의 인덱스는 0 부터 시작합니다.",
        "disalbed(필수) 파라미터로 true 설정 시 해당 아이템을 비활성화 상태로 설정합니다.",
        "disalbed(필수) 파라미터로 false 설정 시 해당 아이템을 활성화 상태로 설정합니다.",
        "해당 아이템의 비활성화 상태를 변경해도 아이템의 선택 상태는 유지됩니다.",
    ]
} 



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        allOption : true,
    }

    let cList = $c.gcm.createCList(properties);

    // target 생성    
    $c.gcm.createBasicCheckComboBox(cList);
}



scwin.btn_getDisabled_onclick = function (e) {

    target1.openTable();

    let comp = "target1_itemTable";
    let targetElements = document.querySelectorAll('[id*='+comp+']');

    let inputs = targetElements[0].querySelectorAll('input.w2table_ccb_col_checkbox');

    // 각 input 요소의 disabled 속성 존재 여부 확인
    inputs.forEach((input, index) => {
        if (input.hasAttribute('disabled')) {            
            wf_body_bottom.getObj("scwin").setReturnValue("Item index=" + index + " 은 비활성화");	
        } else {
            wf_body_bottom.getObj("scwin").setReturnValue("Item index=" + index + " 은 활성화");	
        }
    });	
};



scwin.btn_setItemDisabled_onclick = function (e) {
    let index = par_index.getText();
    let disabled = par_disabled.getText();

	target1.setItemDisabled(index, disabled);
};



scwin.btn_getSelectedInfo_onclick = function (e) {
    let rtn = target1.getSelectedInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("objArray:" +rtn);

    if (rtn) {
        rtn.forEach(function(item, index) {
            wf_body_bottom.getObj("scwin").setReturnValue("Item index="+index+" 의 index : " +item.index);
            wf_body_bottom.getObj("scwin").setReturnValue("Item index="+index+" 의 label : " +item.label);
            wf_body_bottom.getObj("scwin").setReturnValue("Item index="+index+" 의 value : " +item.value);
            wf_body_bottom.getObj("scwin").setReturnValue("Item index="+index+" 의 checked : " +item.checked);
        });          
    }
};
